// 8. SYSTEM ADMIN & SECURITY (10 UCs)
const sysData = [
  ['UC-VN-SYS-01', 'Khởi Tạo Doanh Nghiệp Mới & Phân Cấp Cô Lập Dữ Liệu Multi-Tenant', 'Super Admin hệ thống ViOne', 'Khi có doanh nghiệp mới đăng ký dịch vụ', '1. Đăng nhập Cổng Quản trị Trung tâm (Super Admin Portal).\n2. Nhấn "Thêm Mới Doanh Nghiệp (Tenant)". Nhập tên công ty, mã định danh Tenant ID duy nhất, người đại diện và gói dịch vụ.\n3. Hệ thống tự động tạo không gian lưu trữ cô lập riêng biệt trong cơ sở dữ liệu PostgreSQL.\n4. Cấp phát khóa mã hóa dữ liệu riêng biệt cho Tenant mới.\n5. Tự động gửi thông tin tài khoản quản trị cao nhất tới email của khách hàng.', 'Dữ liệu giữa các doanh nghiệp được ngăn cách tuyệt đối ở tầng kiến trúc cơ sở dữ liệu.', 'Doanh nghiệp mới sẵn sàng đưa vào vận hành ngay trong 60 giây.', '02_crm_members_roles_permission.png', 'Khởi Tạo Doanh Nghiệp Mới & Cơ Chế Cô Lập Dữ Liệu Multi-Tenancy'],
  ['UC-VN-SYS-02', 'Cấu Hình Tên Miền Tùy Biến (Custom Domain) & Chứng Chỉ SSL', 'Quản trị viên IT Doanh nghiệp, Super Admin', 'Doanh nghiệp muốn chạy trên tên miền riêng', '1. Vào mục "Cài Đặt Tên Miền". Nhập tên miền riêng của doanh nghiệp: `erp.congtyban.vn`.\n2. Hệ thống cung cấp các bản ghi DNS cần cấu hình (Bản ghi CNAME trỏ về hệ thống ViOne).\n3. Doanh nghiệp cấu hình DNS trên nhà đăng ký tên miền.\n4. Nhấn "Xác Thực Bản Ghi". Hệ thống kiểm tra kết nối và tự động khởi tạo chứng chỉ bảo mật SSL Let\'s Encrypt miễn phí.\n5. Hệ thống kích hoạt tên miền riêng thành công.', 'Toàn bộ liên kết, email thông báo và giao diện đổi sang thương hiệu tên miền riêng.', 'Nâng cao uy tín và thương hiệu công nghệ chuyên nghiệp của doanh nghiệp.', '01_landing_hero.png', 'Cấu Hình Tên Miền Riêng (Custom Domain) & Tự Động Cấp Chứng Chỉ Bảo Mật SSL'],
  ['UC-VN-SYS-03', 'Quản Lý Người Dùng & Cấp Phát Giấy Phép Sử Dụng (User Licenses)', 'Quản trị viên hệ thống của công ty', 'Có nhân sự mới cần cấp tài khoản', '1. Mở danh sách "Người Dùng Hệ Thống". Bấm "Thêm Người Dùng".\n2. Nhập họ tên, email công vụ và chọn vai trò phân quyền.\n3. Kiểm tra số lượng giấy phép bản quyền (Licenses) còn trống trong gói dịch vụ.\n4. Gán giấy phép cho người dùng và nhấn "Kích Hoạt Tài Khoản".\n5. Khi nhân sự nghỉ việc, bấm "Thu Hồi Giấy Phép" để tái cấp phát cho nhân sự mới.', 'Hệ thống cảnh báo khi số lượng tài khoản sắp chạm trần gói dịch vụ đã mua.', 'Quản lý bản quyền phần mềm minh bạch, tối ưu chi phí đầu tư.', '04_crm_members_management.png', 'Quản Lý Danh Sách Người Dùng & Phân Bổ Bản Quyền Sử Dụng (Licenses)'],
  ['UC-VN-SYS-04', 'Thiết Lập Ma Trận Phân Quyền Vai Trò Nghiêm Ngặt (RBAC Matrix)', 'Quản trị viên An ninh, Ban Giám Đốc', 'Cấu hình quyền hạn theo chức danh', '1. Vào mục "Phân Quyền Vai Trò (Roles & Permissions)".\n2. Xem các vai trò mặc định: Super Admin, Giám Đốc, Trưởng Phòng, Chuyên Viên, Khách Hàng.\n3. Có thể tạo thêm vai trò mới: "Kế Toán Trưởng", "Thực Tập Sinh Kinh Doanh".\n4. Thiết lập ma trận quyền chi tiết cho từng phân hệ: Xem, Thêm mới, Chỉnh sửa, Xóa, Xuất dữ liệu.\n5. Bấm Lưu và áp dụng tức thì cho toàn bộ người dùng thuộc vai trò đó.', 'Ngăn chặn tuyệt đối hành vi truy cập trái phép hoặc xem lén thông tin ngoài thẩm quyền.', 'Bảo vệ bí mật kinh doanh và tuân thủ nguyên tắc phân quyền tối thiểu (Least Privilege).', '02_crm_members_roles_permission.png', 'Ma Trận Phân Quyền Theo Vai Trò (Role-Based Access Control - RBAC) 5 Cấp'],
  ['UC-VN-SYS-05', 'Cấu Hình Xác Thực Hai Yếu Tố Bắt Buộc (Enforce 2FA / MFA)', 'Quản trị viên An ninh Thông tin', 'Nâng cao mức độ bảo vệ tài khoản', '1. Mở mục "Chính Sách Bảo Mật Đăng Nhập".\n2. Bật tùy chọn "Bắt Buộc Xác Thực 2 Lớp (2FA) Cho Toàn Bộ Nhân Viên".\n3. Khi nhân viên đăng nhập lần sau, màn hình yêu cầu quét mã QR liên kết ứng dụng Google Authenticator hoặc Microsoft Authenticator.\n4. Lưu trữ 10 mã dự phòng khẩn cấp (Backup Codes).\n5. Kể từ đó, mỗi lần đăng nhập bắt buộc phải có mã OTP 6 số trên điện thoại.', 'Khóa ngay các tài khoản đăng nhập từ địa chỉ IP nước ngoài bất thường.', 'Ngăn chặn 99.9% nguy cơ bị đánh cắp tài khoản do lộ mật khẩu.', '03_crm_login_page.png', 'Chính Sách Bắt Buộc Xác Thực Đa Yếu Tố 2FA Bảo Vệ Toàn Diện Tài Khoản'],
  ['UC-VN-SYS-06', 'Xem & Truy Vết Nhật Ký Kiểm Toán Hoạt Động (Audit Trail Logging)', 'Ban Kiểm Soát Nội Bộ, Chuyên gia An ninh Mạng', 'Cần điều tra sự cố hoặc rà soát định kỳ', '1. Mở phân hệ "Nhật Ký Kiểm Toán (Audit Trail)".\n2. Xem dòng thời gian toàn bộ các thao tác: Ai làm, Vào lúc nào, Từ địa chỉ IP nào, Thao tác trên bản ghi nào, Giá trị cũ là gì và Giá trị mới đổi thành gì.\n3. Sử dụng bộ lọc tìm kiếm: Lọc các hành vi "Xóa khách hàng" hoặc "Xuất báo cáo tài chính".\n4. Xuất nhật ký kiểm toán ra tệp tin phục vụ thanh tra.', 'Nhật ký kiểm toán được lưu trữ theo cơ chế Bất Biến (Write-Once-Read-Many - WORM), không ai có thể sửa hay xóa nhật ký.', 'Minh bạch 100% mọi hành vi người dùng, làm bằng chứng pháp lý rõ ràng.', '01_crm_login_blue_white.png', 'Trung Tâm Truy Vết Nhật Ký Kiểm Toán Hoạt Động Hệ Thống (Audit Trail)'],
  ['UC-VN-SYS-07', 'Cấu Hình Lịch Tự Động Sao Lưu Cơ Sở Dữ Liệu & Khôi Phục Dự Phòng', 'Quản trị viên Cơ sở Dữ liệu (DBA), DevOps', 'Đảm bảo an toàn dữ liệu doanh nghiệp', '1. Vào mục "Sao Lưu & Khôi Phục (Backup & Restore)".\n2. Cấu hình lịch tự động sao lưu dữ liệu toàn phần (Full Backup) vào 03:00 sáng hàng ngày.\n3. Cấu hình sao lưu vi sai (Incremental Backup) mỗi 2 giờ một lần.\n4. Bản sao lưu được mã hóa AES-256 và tự động đẩy lên 2 vùng trung tâm dữ liệu đám mây độc lập.\n5. Thực hiện định kỳ bài kiểm tra thử nghiệm khôi phục dữ liệu (Recovery Drill) trong 15 phút.', 'Chỉ số cam kết: RPO < 2 giờ (Mất dữ liệu tối đa 2 giờ), RTO < 30 phút (Khôi phục xong trong 30 phút).', 'Bảo đảm an toàn tuyệt đối cho tài sản dữ liệu của doanh nghiệp trước mọi rủi ro thảm họa.', 'operational-dashboard.png', 'Lịch Tự Động Sao Lưu Dữ Liệu Định Kỳ & Phương Án Khôi Phục Sau Thảm Họa'],
  ['UC-VN-SYS-08', 'Giám Sát Sức Khỏe Máy Chủ, Tải Hệ Thống & Thời Gian Phản Hồi API', 'Kỹ sư Vận hành Hệ thống (SRE)', 'Giám sát vận hành 24/7', '1. Mở màn hình "Hạ Tầng & Sức Khỏe Hệ Thống (Infrastructure Monitoring)".\n2. Quan sát các đồ thị: Mức sử dụng CPU máy chủ (Dưới 40%), Bộ nhớ RAM, Lưu lượng mạng Network I/O.\n3. Theo dõi thời gian phản hồi trung bình của API (Dưới 120ms).\n4. Tỷ lệ lỗi HTTP 5xx luôn duy trì ở mức 0.00%.\n5. Khi tải hệ thống tăng đột biến trên 80%, hệ thống tự động kích hoạt cơ chế mở rộng máy chủ tự động (Auto-scaling).', 'Tự động gửi cảnh báo khẩn cấp qua Telegram/SMS cho đội ngũ kỹ thuật khi có nguy cơ quá tải.', 'Đảm bảo hệ sinh thái ViOne luôn vận hành mượt mà, ổn định tuyệt đối.', 'operational-dashboard.png', 'Màn Hình Giám Sát Hiệu Năng Máy Chủ, Tải CPU & Tốc Độ Phản Hồi API Realtime'],
  ['UC-VN-SYS-09', 'Quản Lý Khóa API (API Keys) & Kết Nối Webhook Tích Hợp Phần Mềm Khác', 'Chuyên viên Tích hợp Hệ thống, Lập trình viên', 'Cần kết nối với phần mềm kế toán cũ hoặc ERP', '1. Vào mục "Cổng Lập Trình Viên (Developer API & Webhooks)".\n2. Nhấn "Tạo Khóa API Mới". Đặt tên khóa và giới hạn quyền hạn truy cập.\n3. Sao chép chuỗi mã khóa bí mật (API Secret Key) an toàn.\n4. Cấu hình Webhook URL nhận thông báo khi có sự kiện phát sinh (Ví dụ: Sự kiện thanh toán thành công).\n5. Nhấn "Gửi Thử Nghiệm Webhook (Ping Test)" để xác nhận kết nối thành công.', 'Hỗ trợ tài liệu chuẩn RESTful API Swagger 3.0 chi tiết từng hàm dữ liệu.', 'Kết nối thông suốt hệ sinh thái ViOne với mọi phần mềm có sẵn của doanh nghiệp.', '01_landing_hero.png', 'Quản Lý Khóa API Kết Nối Hệ Thống & Cấu Hình Webhook Tự Động Hóa'],
  ['UC-VN-SYS-10', 'Quản Lý Chính Sách Tiêu Hủy Dữ Liệu & Tuân Thủ Quyền Riêng Tư (GDPR)', 'Giám đốc Pháp chế, Quản trị viên An ninh', 'Khi chấm dứt hợp đồng dịch vụ', '1. Vào mục "Chính Sách Dữ Liệu & Quyền Riêng Tư".\n2. Khi khách hàng yêu cầu thanh lý dịch vụ, kích hoạt quy trình "Xuất Toàn Bộ Dữ Liệu Gốc".\n3. Hệ thống nén toàn bộ cơ sở dữ liệu và tệp đính kèm của Tenant thành tệp mã hóa gửi khách hàng.\n4. Kích hoạt quy trình tiêu hủy dữ liệu vĩnh viễn (Secure Data Erasure) theo tiêu chuẩn quân sự DoD 5220.22-M.\n5. Xuất biên bản xác nhận tiêu hủy dữ liệu sạch sẽ hoàn toàn khỏi hệ thống máy chủ.', 'Không lưu lại bất kỳ bản sao ngầm nào của khách hàng sau khi đã tiêu hủy.', 'Tuân thủ tuyệt đối Luật An ninh Mạng Việt Nam và quy định bảo vệ dữ liệu cá nhân Nghị định 13/2023/NĐ-CP.', '02_crm_members_roles_permission.png', 'Quy Trình Tiêu Hủy Dữ Liệu An Toàn & Tuân Thủ Tiêu Chuẩn Bảo Mật Dữ Liệu']
];

